using System;

public class DockerBuildStep
{
    public string Instruction { get; set; } = "";
    public bool DependsOnSourceCode { get; set; }
}

public class DockerfileAuditor
{
    public static bool IsOptimizedForCaching(DockerBuildStep[] steps)
    {
        int restoreIndex = -1;
        int copyAllIndex = -1;

        for (int i = 0; i < steps.Length; i++)
        {
            if (steps[i].Instruction.Contains("dotnet restore")) restoreIndex = i;
            if (steps[i].Instruction.Contains("COPY . .")) copyAllIndex = i;
        }

        if (restoreIndex != -1 && copyAllIndex != -1)
        {
            return restoreIndex < copyAllIndex;
        }

        return false;
    }
}

public class Program
{
    public static void Main()
    {
        var badDockerfile = new DockerBuildStep[]
        {
            new() { Instruction = "COPY . .", DependsOnSourceCode = true },
            new() { Instruction = "RUN dotnet restore", DependsOnSourceCode = false },
            new() { Instruction = "RUN dotnet publish", DependsOnSourceCode = true }
        };

        var goodDockerfile = new DockerBuildStep[]
        {
            new() { Instruction = "COPY *.csproj .", DependsOnSourceCode = false },
            new() { Instruction = "RUN dotnet restore", DependsOnSourceCode = false },
            new() { Instruction = "COPY . .", DependsOnSourceCode = true },
            new() { Instruction = "RUN dotnet publish", DependsOnSourceCode = true }
        };

        Console.WriteLine($"Dockerfile Buruk Teroptimasi? : {DockerfileAuditor.IsOptimizedForCaching(badDockerfile)} (Ekspektasi: False)");
        Console.WriteLine($"Dockerfile Bagus Teroptimasi? : {DockerfileAuditor.IsOptimizedForCaching(goodDockerfile)} (Ekspektasi: True)");
    }
}
